INSERT OR REPLACE INTO runbooks (slug, category, error_code, title, summary, root_cause, diagnostic_command, solution_steps, tags, source_url) VALUES ('k8s-pod-oom-killed', 'kubernetes', 'OOMKilled / Exit Code 137', 'Pod Terminated with OOMKilled (Exit Code 137)', 'The Linux kernel killed the container process because it exceeded its container memory limits configured in `resources.limits.memory` (or the host node exhausted its memory).', 'When cgroup memory usage hits the hard limit set in the Pod specification, Linux triggers the kernel Out-Of-Memory (OOM) killer. The kernel sends SIGKILL (9) to the primary container process, terminating it immediately with exit code 128 + 9 = 137.', 'kubectl describe pod <pod-name> -n <namespace> | grep -E "(OOMKilled|Exit Code|Limits|Requests)"', '[{"step":1,"action":"Verify OOM status","command":"Check pod status with `kubectl get pod <pod-name> -o jsonpath=''{.status.containerStatuses[*].lastState.terminated.reason}''` (Confirm it says `OOMKilled`).","expected":"Verified resolution"},{"step":2,"action":"Review Memory Metrics","command":"Run `kubectl top pod <pod-name> --containers` to observe memory consumption leading up to the crash.","expected":"Verified resolution"},{"step":3,"action":"Inspect JVM / Node Heap Settings","command":"Verify that application heap ceilings (e.g. `-Xmx`, `--max-old-space-size`) leave at least 25% headroom for non-heap native memory (metaspace, thread stacks, buffers).","expected":"Verified resolution"},{"step":4,"action":"Adjust Kubernetes Resource Limits","command":"Bump `resources.limits.memory` in the Deployment manifest to accommodate legitimate load spikes.","expected":"Verified resolution"}]', '["kubernetes","oom","cgroups","memory","limits","requests"]', 'https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/');